/**
 * One cover per session, shown behind the card's title/time/room and behind the session page headline.
 * Two kinds, so a long program doesn't read as one wall of stock photos:
 * - photo: free-license Unsplash photos, hot-linked from Unsplash's CDN (as the Awards page does).
 *   To change one, replace the photo id (the part after images.unsplash.com/).
 * - diagram: an academic figure drawn for this prototype (source/shared/diagrams, generated by
 *   source/scripts/diagrams.py), each in the figure style its field would use.
 */
const covers: Record<string, { photo: string } | { diagram: string }> = {
  'ai-shared-control': { photo: 'photo-1682159672286-40790338349b' },        // child touching a robotic hand
  'access-beyond-compliance': { photo: 'photo-1732194439368-4655fd0ea955' }, // woman in a wheelchair
  'tangible-futures': { photo: 'photo-1422246358533-95dcd3d48961' },         // potter's clay-stained hand
  'community-moderation': { diagram: 'network' },                            // community network graph
  'wellbeing-boundaries': { diagram: 'heatmap' },                            // week × hour activity heatmap
  'creative-tools': { photo: 'photo-1522542550221-31fd19575a2d' },           // watercolor wireframe sketches
  'robots-in-public': { photo: 'photo-1771707397168-028abef1d651' },         // delivery robot on a sidewalk
  'learning-together': { photo: 'photo-1509062522246-3755977927d7' },        // classroom with teacher
  'healthcare-handoffs': { diagram: 'swimlane' },                            // clinical handoff swimlane
  'platform-labor': { diagram: 'sankey' },                                   // worker-flow Sankey
  'privacy-practice': { diagram: 'venn' },                                   // hand-drawn Venn in a notebook
  'voice-and-sound': { diagram: 'spectrogram' },                             // spectrogram + waveform
  'climate-adaptation': { diagram: 'contour' },                              // contour map with flood extent
  'playful-bodies': { photo: 'photo-1529229504105-4ea795dcbf59' },           // dancer, long exposure
  'methods-and-power': { diagram: 'matrix' },                                // 2×2 matrix scatter, paper style
}

/** Cover URL for a session, sized for where it is shown (diagrams are vector, so width is ignored). */
export function sessionImage(id: string, width = 900): string | undefined {
  const cover = covers[id]
  if (!cover) return undefined
  return 'photo' in cover
    ? `https://images.unsplash.com/${cover.photo}?w=${width}&q=70&auto=format&fit=crop`
    // Absolute: a relative url() inside a CSS variable resolves against the stylesheet (program/assets/), not the page.
    : new URL(`../shared/diagrams/${cover.diagram}.svg`, document.baseURI).href
}
